import AppKit
import XCTest
@testable import pType

@MainActor
final class NavigationLiveRegressionTests: XCTestCase {
    func testLongDocumentFindAndOutlineUseActualWindowEditor() throws {
        // Same contents as the 100-heading document that failed live acceptance.
        let source = "# Review start\n\n[[Visible|opaque-review]] 🧭 first [^note] second [^note].\n\n[^note]: review definition\n\n"
            + (1...100).map { String(format: "## Section %03d\n\nBody for section %d.\n\n", $0, $0) }.joined()
        let document = PTypeDocument()
        try document.read(from: Data(source.utf8), ofType: "net.daringfireball.markdown")
        document.makeWindowControllers()
        document.showWindows()
        defer { document.windowControllers.forEach { $0.close() } }
        let controller = try XCTUnwrap(document.windowControllers.first as? PTypeWindowController)
        let window = try XCTUnwrap(controller.window)
        window.setFrame(NSRect(x: 100, y: 100, width: 800, height: 684), display: true)
        drain()
        let editor = try XCTUnwrap(document.undoPublicationTextView)
        let map = SourceDisplayMap(engineDocumentId: document.session.engineDocumentId, revision: document.session.revision, source: source)
        XCTAssertEqual(editor.string, map.display)
        controller.showFind(nil)
        drain()
        controller.navigation.updateFindQuery("Section 050")
        XCTAssertEqual(controller.navigation.findResults.count, 1)
        XCTAssertTrue(controller.navigation.selectNextFindResult())
        drain()
        XCTAssertTrue(window.firstResponder === editor)
        XCTAssertEqual(editor.selectedRange(), (editor.string as NSString).range(of: "Section 050"))
        XCTAssertGreaterThan(try XCTUnwrap(editor.enclosingScrollView).contentView.bounds.origin.y, 0)
        controller.showOutline(nil)
        drain()
        let overlay = try XCTUnwrap(window.contentView?.subviews.compactMap { $0 as? OutlineOverlayView }.first)
        let search = try XCTUnwrap(findSearchField(in: overlay))
        window.makeFirstResponder(search)
        let fieldEditor = try XCTUnwrap(window.firstResponder as? NSTextView)
        fieldEditor.selectAll(nil)
        fieldEditor.insertText("090", replacementRange: fieldEditor.selectedRange())
        drain()
        let entry = try XCTUnwrap(controller.navigation.index.map(HeadingOutline.make(from:))?.first { $0.title == "Section 090" })
        XCTAssertTrue(controller.navigate(to: entry))
        drain()
        XCTAssertEqual(editor.selectedRange().location, (editor.string as NSString).range(of: "## Section 090").location)
        XCTAssertGreaterThan(try XCTUnwrap(editor.enclosingScrollView).contentView.bounds.origin.y, 0)
        XCTAssertNil(window.contentView?.subviews.compactMap { $0 as? OutlineOverlayView }.first)
        let targetRange = (editor.string as NSString).range(of: "Section 090")
        let screenRect = editor.firstRect(forCharacterRange: targetRange, actualRange: nil)
        let editorRect = editor.convert(window.convertFromScreen(screenRect), from: nil)
        XCTAssertTrue(editor.visibleRect.intersects(editorRect), "Outline must reveal Section 090 after its overlay closes")
        XCTAssertEqual(document.session.source, source)
    }

    private func findSearchField(in view: NSView) -> NSTextField? {
        if let field = view as? NSTextField, field.placeholderString == "Search headings" { return field }
        return view.subviews.lazy.compactMap(findSearchField).first
    }

    private func drain() {
        for _ in 0..<40 { RunLoop.main.run(until: Date().addingTimeInterval(0.01)) }
    }

    func testMissingFootnoteTargetStaysDisabledAfterNativeMenuValidation() throws {
        let document = PTypeDocument()
        try document.read(from: Data("Prose [^missing]\n".utf8), ofType: "net.daringfireball.markdown")
        document.makeWindowControllers()
        document.showWindows()
        defer { document.windowControllers.forEach { $0.close() } }
        drain()
        let editor = try XCTUnwrap(document.undoPublicationTextView)
        let reference = (editor.string as NSString).range(of: "[^missing]")
        editor.setSelectedRange(reference)
        let screenRect = editor.firstRect(forCharacterRange: reference, actualRange: nil)
        let window = try XCTUnwrap(editor.window)
        let point = window.convertPoint(fromScreen: NSPoint(x: screenRect.midX, y: screenRect.midY))
        let event = try XCTUnwrap(NSEvent.mouseEvent(with: .rightMouseDown, location: point, modifierFlags: [], timestamp: 0, windowNumber: window.windowNumber, context: nil, eventNumber: 1, clickCount: 1, pressure: 1))
        let menu = try XCTUnwrap(editor.menu(for: event))
        let item = try XCTUnwrap(menu.item(withTitle: "Go to Footnote Definition"))
        XCTAssertTrue(menu.autoenablesItems)
        menu.update()
        XCTAssertFalse(item.isEnabled)
    }

    func testFindRevealsMatchedLineInsideLongWrappedParagraph() throws {
        let source = String(repeating: "A long paragraph continues with text. ", count: 300) + "MATCH-END\n"
        let document = PTypeDocument()
        try document.read(from: Data(source.utf8), ofType: "net.daringfireball.markdown")
        document.makeWindowControllers()
        document.showWindows()
        defer { document.windowControllers.forEach { $0.close() } }
        drain()
        let controller = try XCTUnwrap(document.windowControllers.first as? PTypeWindowController)
        let editor = try XCTUnwrap(document.undoPublicationTextView)
        controller.navigation.updateFindQuery("MATCH-END")
        XCTAssertTrue(controller.navigation.selectNextFindResult())
        drain()
        let screenRect = editor.firstRect(forCharacterRange: editor.selectedRange(), actualRange: nil)
        let window = try XCTUnwrap(editor.window)
        let editorRect = editor.convert(window.convertFromScreen(screenRect), from: nil)
        XCTAssertTrue(editor.visibleRect.intersects(editorRect), "Selected match must be visible, including matches far inside one paragraph")
    }
}
import AppKit
import PTypeCore
import XCTest
@testable import pType

@MainActor
final class NavigationTests: XCTestCase {
    private let profile = SerializationProfile(hasByteOrderMark: false, lineEnding: .lf, hadMixedLineEndings: false)

    func testFindUsesCommittedSourceCaseInsensitivelyAndRefreshesStaleResults() {
        let session = DocumentSession(source: "One 🧭 one [[Name|id]] ONE", profile: profile, fileIdentifier: "find")
        let navigation = NavigationController(session: session)

        navigation.updateFindQuery("one")
        XCTAssertEqual(navigation.findResults.map(\.sourceRange), [
            NSRange(location: 0, length: 3), NSRange(location: 7, length: 3), NSRange(location: 23, length: 3),
        ])
        XCTAssertEqual(navigation.findResults.map(\.revision), [0, 0, 0])

        session.commitFromEngine("One plus one", engineDocumentId: session.engineDocumentId)
        navigation.selectNextFindResult()
        XCTAssertEqual(navigation.findResults.map(\.revision), [1, 1])
    }

    func testNavigationRejectsStaleOrMismatchedProjectionAndMapsWikiLinks() {
        let source = "# [[Name|opaque]] 🧭\n"
        let session = DocumentSession(source: source, profile: profile, fileIdentifier: "map")
        let textView = NSTextView()
        let navigation = NavigationController(session: session, engineAccess: EngineAccess(textView: textView))
        let range = (source as NSString).range(of: "🧭")

        textView.string = source
        XCTAssertFalse(navigation.navigate(toSourceRange: range, revision: 0))

        let map = SourceDisplayMap(engineDocumentId: session.engineDocumentId, revision: 0, source: source)
        textView.string = map.display
        XCTAssertTrue(navigation.navigate(toSourceRange: range, revision: 0))
        XCTAssertEqual(textView.selectedRange(), map.displayRange(forSourceRange: range))

        session.commitFromEngine(source + "more", engineDocumentId: session.engineDocumentId)
        XCTAssertFalse(navigation.navigate(toSourceRange: range, revision: 0))
    }

    func testFootnoteReturnUsesLastVisitedExistingReferenceThenFirst() {
        let source = "a [^x], b [^x].\n\n[^x]: note\n"
        let session = DocumentSession(source: source, profile: profile, fileIdentifier: "footnotes")
        let textView = NSTextView()
        textView.string = source
        let navigation = NavigationController(session: session, engineAccess: EngineAccess(textView: textView))
        navigation.apply(index: IndexBuilder.build(source: source, revision: 0), engineDocumentId: session.engineDocumentId)
        let references = navigation.index!.footnoteReferences
        let definition = navigation.index!.footnoteDefinitions[0]

        textView.setSelectedRange(NSRange(location: references[1].range.location, length: 0))
        XCTAssertTrue(navigation.goToFootnoteDefinition())
        XCTAssertEqual(textView.selectedRange().location, definition.markerRange.location)
        XCTAssertTrue(navigation.goToFootnoteReference())
        XCTAssertEqual(textView.selectedRange().location, references[1].range.location)

        session.commitFromEngine("a [^x].\n\n[^x]: note\n", engineDocumentId: session.engineDocumentId)
        let updated = IndexBuilder.build(source: session.source, revision: session.revision)
        navigation.apply(index: updated, engineDocumentId: session.engineDocumentId)
        textView.string = session.source
        textView.setSelectedRange(NSRange(location: updated.footnoteDefinitions[0].range.location, length: 0))
        XCTAssertTrue(navigation.goToFootnoteReference())
        XCTAssertEqual(textView.selectedRange().location, updated.footnoteReferences[0].range.location)
    }

    func testOutlineOverlayFrameStaysInsideWindowAndBelowAnchor() {
        let frame = OutlineOverlayLayout.frame(
            anchor: NSRect(x: 760, y: 550, width: 30, height: 30),
            contentBounds: NSRect(x: 0, y: 0, width: 800, height: 580),
            preferredSize: NSSize(width: 340, height: 380)
        )
        XCTAssertEqual(frame.maxX, 792, accuracy: 0.5)
        XCTAssertEqual(frame.maxY, 550, accuracy: 0.5)
        XCTAssertGreaterThanOrEqual(frame.minX, 0)
        XCTAssertGreaterThanOrEqual(frame.minY, 0)

        let narrow = OutlineOverlayLayout.frame(
            anchor: NSRect(x: 120, y: 180, width: 20, height: 20),
            contentBounds: NSRect(x: 0, y: 0, width: 150, height: 200),
            preferredSize: NSSize(width: 340, height: 380)
        )
        XCTAssertEqual(narrow.width, 134, accuracy: 0.5)
        XCTAssertLessThanOrEqual(narrow.maxX, 142)
        XCTAssertLessThanOrEqual(narrow.maxY, 180)

        let titlebarAnchor = OutlineOverlayLayout.frame(
            anchor: NSRect(x: 760, y: 610, width: 30, height: 30),
            contentBounds: NSRect(x: 0, y: 0, width: 800, height: 580),
            preferredSize: NSSize(width: 340, height: 380)
        )
        XCTAssertEqual(titlebarAnchor.maxY, 572, accuracy: 0.5)

        let insetAnchor = OutlineOverlayLayout.frame(
            anchor: NSRect(x: 600, y: 550, width: 30, height: 30),
            contentBounds: NSRect(x: 0, y: 0, width: 800, height: 580),
            preferredSize: NSSize(width: 340, height: 380)
        )
        XCTAssertEqual(insetAnchor.maxX, 792, accuracy: 0.5)
    }

    func testIndexSchedulingDebouncesEditsAndPublishesNewestRevision() {
        let session = DocumentSession(source: "# Zero\n", profile: profile, fileIdentifier: "scheduler")
        let navigation = NavigationController(session: session)
        navigation.scheduleCurrentIndex(immediate: true)
        waitUntil { navigation.index?.revision == 0 }

        session.commitFromEngine("# One\n", engineDocumentId: session.engineDocumentId)
        navigation.scheduleCurrentIndex()
        session.commitFromEngine("# Two\n", engineDocumentId: session.engineDocumentId)
        navigation.scheduleCurrentIndex()
        RunLoop.current.run(until: Date(timeIntervalSinceNow: 0.05))
        XCTAssertEqual(navigation.index?.headings.first?.title, "Zero")
        waitUntil { navigation.index?.revision == 2 }
        XCTAssertEqual(navigation.index?.headings.first?.title, "Two")
    }

    func testContextMenuUsesSelectionAndDisablesMissingFootnoteTarget() throws {
        let source = "[^ok] [^missing]\n\n[^ok]: note\n"
        let session = DocumentSession(source: source, profile: profile, fileIdentifier: "context")
        let textView = NSTextView()
        textView.string = source
        let navigation = NavigationController(session: session, engineAccess: EngineAccess(textView: textView))
        navigation.apply(index: IndexBuilder.build(source: source, revision: 0), engineDocumentId: session.engineDocumentId)

        let okMenu = navigation.buildContextMenu(NSMenu(), selection: (source as NSString).range(of: "[^ok]"))
        XCTAssertTrue(try XCTUnwrap(okMenu.item(withTitle: "Go to Footnote Definition")).isEnabled)
        let missingMenu = navigation.buildContextMenu(NSMenu(), selection: (source as NSString).range(of: "[^missing]"))
        XCTAssertFalse(try XCTUnwrap(missingMenu.item(withTitle: "Go to Footnote Definition")).isEnabled)
    }

    func testNavigationMenuShortcutsAreInstalled() throws {
        let menu = PTypeMenuInstaller.makeMainMenu()
        let edit = try XCTUnwrap(menu.item(withTitle: "Edit")?.submenu)
        XCTAssertEqual(edit.item(withTag: 9_520)?.keyEquivalentModifierMask, [.command])
        XCTAssertEqual(edit.item(withTag: 9_521)?.keyEquivalentModifierMask, [.command])
        XCTAssertEqual(edit.item(withTag: 9_522)?.keyEquivalentModifierMask, [.command, .shift])
        let go = try XCTUnwrap(menu.item(withTitle: "Go")?.submenu)
        XCTAssertEqual(go.item(withTag: 9_523)?.keyEquivalentModifierMask, [.command, .option])
        XCTAssertEqual(go.item(withTag: 9_524)?.keyEquivalentModifierMask, [.command, .option])
    }

    func testCommittedDialectFixturesUseSharedIndex() throws {
        let bundle = Bundle(for: Self.self)
        let mixedURL = try XCTUnwrap(bundle.url(forResource: "mixed", withExtension: "md", subdirectory: "Fixtures/dialect") ?? bundle.url(forResource: "mixed", withExtension: "md"))
        let malformedURL = try XCTUnwrap(bundle.url(forResource: "malformed", withExtension: "md", subdirectory: "Fixtures/dialect") ?? bundle.url(forResource: "malformed", withExtension: "md"))
        let mixed = try String(contentsOf: mixedURL, encoding: .utf8)
        let malformed = try String(contentsOf: malformedURL, encoding: .utf8)

        let mixedIndex = IndexBuilder.build(source: mixed, revision: 4)
        XCTAssertNotNil(mixedIndex.frontMatter)
        XCTAssertEqual(mixedIndex.headings.map(\.title), ["Heading with [[First|opaque-1]]"])
        XCTAssertEqual(mixedIndex.listItems.count, 3)
        XCTAssertEqual(mixedIndex.listItems.compactMap(\.taskMarkerRange).count, 2)
        XCTAssertEqual(mixedIndex.fences.count, 1)
        XCTAssertEqual(mixedIndex.footnoteReferences.map(\.label), ["one"])
        XCTAssertEqual(mixedIndex.footnoteDefinitions.map(\.label), ["one"])

        let malformedIndex = IndexBuilder.build(source: malformed, revision: 5)
        XCTAssertNil(malformedIndex.frontMatter)
        XCTAssertEqual(malformedIndex.headings.map(\.title), ["Heading"])
        XCTAssertEqual(malformedIndex.fences.count, 1)
        XCTAssertEqual(malformedIndex.footnoteReferences.map(\.label), ["missing"])
    }

    func testOutlineOverlayIsAttachedOnlyToItsDocumentWindow() throws {
        let first = PTypeDocument(source: "# One\n", profile: profile, fileIdentifier: "overlay-one")
        let second = PTypeDocument(source: "# Two\n", profile: profile, fileIdentifier: "overlay-two")
        first.makeWindowControllers()
        second.makeWindowControllers()
        defer {
            first.windowControllers.forEach { $0.close() }
            second.windowControllers.forEach { $0.close() }
        }
        let firstController = try XCTUnwrap(first.windowControllers.first as? PTypeWindowController)
        let secondController = try XCTUnwrap(second.windowControllers.first as? PTypeWindowController)
        firstController.showWindow(nil)
        secondController.showWindow(nil)
        firstController.showOutline(nil)

        let firstContent = try XCTUnwrap(firstController.window?.contentView)
        let secondContent = try XCTUnwrap(secondController.window?.contentView)
        let overlay = try XCTUnwrap(firstContent.subviews.compactMap { $0 as? OutlineOverlayView }.first)
        XCTAssertTrue(firstContent.bounds.contains(overlay.frame))
        XCTAssertTrue(secondContent.subviews.compactMap { $0 as? OutlineOverlayView }.isEmpty)
        firstController.showOutline(nil)
        XCTAssertTrue(firstContent.subviews.compactMap { $0 as? OutlineOverlayView }.isEmpty)
    }

    func testOutlineEntryCarriesIndexRevisionAndStaleJumpIsRejected() throws {
        let source = "# First\n\n## Target\n"
        let session = DocumentSession(source: source, profile: profile, fileIdentifier: "stale-outline")
        let textView = NSTextView()
        textView.string = source
        let navigation = NavigationController(session: session, engineAccess: EngineAccess(textView: textView))
        let index = IndexBuilder.build(source: source, revision: 0)
        navigation.apply(index: index, engineDocumentId: session.engineDocumentId)
        let entry = try XCTUnwrap(HeadingOutline.make(from: index).last)
        XCTAssertEqual(entry.revision, 0)

        session.commitFromEngine("Inserted\n" + source, engineDocumentId: session.engineDocumentId)
        textView.string = session.source
        let selectionBeforeJump = textView.selectedRange()
        let split = NSSplitViewController()
        let window = NSWindow(contentViewController: split)
        let windowController = PTypeWindowController(
            window: window,
            splitViewController: split,
            session: session,
            navigation: navigation,
            editorPanelView: NSView()
        )
        XCTAssertFalse(windowController.navigate(to: entry))
        XCTAssertEqual(textView.selectedRange(), selectionBeforeJump)
    }

    func testEveryShowFindRequestsFocusAgain() {
        let session = DocumentSession(source: "needle", profile: profile, fileIdentifier: "find-focus")
        let navigation = NavigationController(session: session)

        navigation.showFind()
        let firstRequest = navigation.findFocusRequest
        navigation.showFind()

        XCTAssertTrue(navigation.isFindVisible)
        XCTAssertGreaterThan(navigation.findFocusRequest, firstRequest)
    }

    func testLateEngineAttachObservesActiveHeadingAndClearsItOnProjectionMismatch() {
        let source = "# First\n\n## Second\n"
        let session = DocumentSession(source: source, profile: profile, fileIdentifier: "late-attach")
        let navigation = NavigationController(session: session)
        navigation.apply(index: IndexBuilder.build(source: source, revision: 0), engineDocumentId: session.engineDocumentId)
        let container = NSView()
