        navigation.attach(to: container)
        RunLoop.current.run(until: Date(timeIntervalSinceNow: 0.05))
        XCTAssertNil(navigation.activeHeadingLocation)

        let second = (source as NSString).range(of: "## Second")
        textView.setSelectedRange(NSRange(location: second.location, length: 0))
        NotificationCenter.default.post(name: NSTextView.didChangeSelectionNotification, object: textView)
        XCTAssertNil(navigation.activeHeadingLocation, "resolution must not run inside the selection notification")
        waitUntil { navigation.activeHeadingLocation == second.location }
    }

    func testShowFindRefocusesAlreadyVisibleFindFieldAfterNavigation() throws {
        let document = PTypeDocument(source: "needle here", profile: profile, fileIdentifier: "find-refocus")
        document.makeWindowControllers()
        defer { document.windowControllers.forEach { $0.close() } }
        let controller = try XCTUnwrap(document.windowControllers.first as? PTypeWindowController)
        let window = try XCTUnwrap(controller.window)
        controller.showWindow(nil)
        window.makeKeyAndOrderFront(nil)

        controller.showFind(nil)
        var field: NSTextField?
        waitUntil {
            field = self.findTextField(in: window.contentView, placeholder: "Find")
            return field?.currentEditor() === window.firstResponder
        }
        controller.navigation.updateFindQuery("needle")
        controller.findNext(nil)
        XCTAssertFalse(field?.currentEditor() === window.firstResponder)

        controller.showFind(nil)
        waitUntil { field?.currentEditor() === window.firstResponder }
    }

    private func waitUntil(timeout: TimeInterval = 2, _ condition: () -> Bool) {
        let deadline = Date(timeIntervalSinceNow: timeout)
        while !condition(), Date() < deadline {
            RunLoop.current.run(mode: .default, before: Date(timeIntervalSinceNow: 0.01))
        }
        XCTAssertTrue(condition())
    }

    private func findTextField(in view: NSView?, placeholder: String) -> NSTextField? {
        guard let view else { return nil }
        if let field = view as? NSTextField, field.placeholderString == placeholder { return field }
        return view.subviews.lazy.compactMap { self.findTextField(in: $0, placeholder: placeholder) }.first
    }
}
