import AppKit
import PTypeCore

/// Collapses heading sections and list branches in the engine's text view. Folding is a layout projection:
/// hidden paragraphs keep their characters and attributes in storage and only lose their
/// height, so copy, find, undo, and save see the whole document.
@MainActor
final class FoldController {
    private(set) var model = FoldModel()
    /// In document order. Fresh from the index, or shifted along with the edits since;
    /// see ``hasFreshSections``.
    private(set) var sections: [FoldSection] = []
    /// False from the first edit after the index until the next index arrives. The gutter
    /// draws with shifted sections meanwhile; fold commands wait for fresh ones.
    private(set) var hasFreshSections = false
    private(set) weak var textView: NSTextView?
    private var layoutDelegate: FoldingLayoutDelegate?
    private var storageObserver: NSObjectProtocol?
    private var gutter: EditorGutterView?
    private var numbers: LineNumberGutterView?
    /// Set before the first attach; the gutter reads it on every draw.
    var lineNumbers: LineNumberPreference = .shared
    private var lastCaret = 0
    /// Layout invalidation cannot run inside the storage's own edit; it waits for the next turn.
    private var pendingInvalidation: [NSRange] = []

    var hiddenRanges: [NSRange] { model.hiddenRanges }
    var hasFolds: Bool { !model.isEmpty }

    isolated deinit {
        if let storageObserver { NotificationCenter.default.removeObserver(storageObserver) }
    }

    // MARK: Attachment

    /// Proxies the engine's layout delegate on the given text view. A new text view, as after
    /// an external reload, starts without folds; stale hidden ranges must never survive it.
    func attach(to textView: NSTextView) {
        guard textView !== self.textView, let layoutManager = textView.textLayoutManager else { return }
        detach()
        self.textView = textView
        model = FoldModel()
        sections = []
        hasFreshSections = false
        lastCaret = textView.selectedRange().location
        // Every fragment asks; without folds the answer is no before any offset is computed.
        let proxy = FoldingLayoutDelegate(forwarding: layoutManager.delegate) { [weak self] layoutManager, location in
            guard let self, !self.model.isEmpty, let content = layoutManager.textContentManager else { return false }
            return self.model.isHidden(content.offset(from: layoutManager.documentRange.location, to: location))
        }
        layoutManager.delegate = proxy
        layoutDelegate = proxy
        storageObserver = NotificationCenter.default.addObserver(
            forName: NSTextStorage.didProcessEditingNotification,
            object: textView.textStorage,
            queue: nil
        ) { [weak self] notification in
            guard let storage = notification.object as? NSTextStorage,
                  storage.editedMask.contains(.editedCharacters) else { return }
            let edited = storage.editedRange
            let delta = storage.changeInLength
            MainActor.assumeIsolated { self?.storageDidChange(edited: edited, delta: delta) }
        }
        let gutter = EditorGutterView(controller: self)
        gutter.frame = textView.bounds
        gutter.autoresizingMask = [.width, .height]
        textView.addSubview(gutter)
        self.gutter = gutter
        // Beside the text view, not inside it: the reading column is centred and narrower
        // than the window, so numbers drawn relative to it would drift with every resize.
        if let container = textView.superview {
            let numbers = LineNumberGutterView(controller: self)
            numbers.frame = container.bounds
            numbers.autoresizingMask = [.width, .height]
            container.addSubview(numbers, positioned: .above, relativeTo: textView)
            self.numbers = numbers
        }
    }

    private func detach() {
        if let storageObserver { NotificationCenter.default.removeObserver(storageObserver) }
        storageObserver = nil
        if let textView, let layoutDelegate, textView.textLayoutManager?.delegate === layoutDelegate {
            textView.textLayoutManager?.delegate = layoutDelegate.forwarded
        }
        (textView?.string as NSString?)?.length ?? 0
    }

