import AppKit
import PTypeCore
import XCTest
@testable import pType

@MainActor
final class FoldingTests: XCTestCase {
    private let source = "# Alpha\n\nAlpha body one.\n\n## Beta\n\nBeta body.\n\n# Gamma\n\nGamma body.\n"

    private func sections(for source: String) -> [FoldSection] {
        let index = IndexBuilder.build(source: source, revision: 0)
        return FoldSection.make(from: index, map: SourceDisplayMap(engineDocumentId: "t", revision: 0, source: source))
    }

    private func range(of needle: String, in text: String) -> NSRange {
        (text as NSString).range(of: needle)
    }

    // MARK: Model

    func testSectionsHideEverythingUpToTheNextHeadingOfEqualOrHigherLevel() {
        let sections = self.sections(for: source)
        XCTAssertEqual(sections.map(\.title), ["Alpha", "Beta", "Gamma"])
        let alpha = sections[0], beta = sections[1], gamma = sections[2]
        let gammaStart = range(of: "# Gamma", in: source).location
        XCTAssertEqual(alpha.headingLocation, 0)
        XCTAssertEqual(alpha.hidden, NSRange(location: ("# Alpha\n" as NSString).length, length: gammaStart - ("# Alpha\n" as NSString).length))
        XCTAssertEqual(beta.hidden.location, NSMaxRange(range(of: "## Beta\n", in: source)))
        XCTAssertEqual(NSMaxRange(beta.hidden), gammaStart)
        XCTAssertTrue(gamma.canFold)
        XCTAssertEqual(NSMaxRange(gamma.hidden), (source as NSString).length)
        XCTAssertFalse(self.sections(for: "# Only\n").first!.canFold)
        // The caret on the heading line, in the body, and at the document end all belong to a section.
        let length = (source as NSString).length
        XCTAssertEqual(sections.innermost(containing: 3, documentLength: length)?.title, "Alpha")
        XCTAssertEqual(sections.innermost(containing: range(of: "Beta body", in: source).location, documentLength: length)?.title, "Beta")
        XCTAssertEqual(sections.innermost(containing: length, documentLength: length)?.title, "Gamma")
        XCTAssertEqual(sections.enclosing(range(of: "Beta body", in: source).location, documentLength: length).map(\.title), ["Alpha", "Beta"])
    }

    /// Applies the edit to the text the way the storage reports it, then runs both checks.
    private func edit(_ model: inout FoldModel, _ text: inout String, replacing range: NSRange, with replacement: String) -> Int {
        text = (text as NSString).replacingCharacters(in: range, with: replacement)
        let dropped = model.textDidChange(replacing: range, insertedLength: (replacement as NSString).length)
        return dropped.count + model.dropFoldsWithBrokenLines(in: text as NSString).count
    }

    func testFoldsShiftWithEditsAroundThemAndExpandWhenTouched() {
        let sections = self.sections(for: source)
        var model = FoldModel()
        model.fold(sections[1])
        let beta = model.folds[0]
        var text = source

        // Forward delete at the end of the heading joins hidden text to the heading: expand.
        var touched = model
        var touchedText = text
        XCTAssertEqual(edit(&touched, &touchedText, replacing: NSRange(location: beta.hidden.location - 1, length: 1), with: ""), 1)
        XCTAssertTrue(touched.isEmpty)
        // Backspace at the start of the next heading eats the last hidden character: expand.
        touched = model
        touchedText = text
        XCTAssertEqual(edit(&touched, &touchedText, replacing: NSRange(location: NSMaxRange(beta.hidden) - 1, length: 1), with: ""), 1)
        // Removing one of the two line breaks before the heading keeps it a paragraph; removing both dissolves it.
        touched = model
        touchedText = text
        XCTAssertEqual(edit(&touched, &touchedText, replacing: NSRange(location: beta.headingLocation - 1, length: 1), with: ""), 0)
        XCTAssertEqual(touched.folds[0].headingLocation, beta.headingLocation - 1)
        touched = model
        touchedText = text
        XCTAssertEqual(edit(&touched, &touchedText, replacing: NSRange(location: beta.headingLocation - 2, length: 2), with: ""), 1)
        // A paste that lands inside the hidden text: expand.
        touched = model
        touchedText = text
        XCTAssertEqual(edit(&touched, &touchedText, replacing: NSRange(location: beta.hidden.location + 2, length: 0), with: "abc"), 1)
        // A selection replaced across the fold's end: expand.
        touched = model
        touchedText = text
        XCTAssertEqual(edit(&touched, &touchedText, replacing: NSRange(location: NSMaxRange(beta.hidden) - 3, length: 6), with: "-"), 1)

        // Typing in the heading title moves the content, not the heading.
        XCTAssertEqual(edit(&model, &text, replacing: NSRange(location: beta.headingLocation + 7, length: 0), with: " x"), 0)
        XCTAssertEqual(model.folds[0].headingLocation, beta.headingLocation)
        XCTAssertEqual(model.folds[0].hidden.location, beta.hidden.location + 2)
        // The storage pads a title edit to the heading's line break; that must not expand.
        XCTAssertEqual(edit(&model, &text, replacing: NSRange(location: model.folds[0].hidden.location - 1, length: 1), with: "y\n"), 0)
        XCTAssertEqual(model.folds[0].hidden.location, beta.hidden.location + 3)
        // Text before the heading moves both.
        XCTAssertEqual(edit(&model, &text, replacing: NSRange(location: 2, length: 1), with: ""), 0)
        XCTAssertEqual(model.folds[0].headingLocation, beta.headingLocation - 1)
        XCTAssertEqual(model.folds[0].hidden.location, beta.hidden.location + 2)
        // Text after the fold leaves it alone.
        let after = NSMaxRange(model.folds[0].hidden)
        XCTAssertEqual(edit(&model, &text, replacing: NSRange(location: after, length: 0), with: "12345"), 0)
        XCTAssertEqual(NSMaxRange(model.folds[0].hidden), after)
        // Return at the end of the heading line inserts before the hidden content.
        let contentStart = model.folds[0].hidden.location
        XCTAssertEqual(edit(&model, &text, replacing: NSRange(location: contentStart - 1, length: 0), with: "\n"), 0)
        XCTAssertEqual(model.folds, [HeadingFold(headingLocation: beta.headingLocation - 1, hidden: NSRange(location: beta.hidden.location + 3, length: beta.hidden.length))])
    }

    func testSectionsFollowEditsUntilTheIndexCatchesUp() {
        let sections = self.sections(for: source)
        let beta = sections[1]
        func shifted(_ range: NSRange, _ replacement: String) -> FoldSection {
            beta.shifted(replacing: range, insertedLength: (replacement as NSString).length)
        }
        // Text before the heading moves the whole section.
        var moved = shifted(NSRange(location: 0, length: 0), "Intro\n")
        XCTAssertEqual(moved.headingLocation, beta.headingLocation + 6)
        XCTAssertEqual(moved.headingRange, NSRange(location: beta.headingRange.location + 6, length: beta.headingRange.length))
        XCTAssertEqual(moved.hidden, NSRange(location: beta.hidden.location + 6, length: beta.hidden.length))
        // Typing in the title, and the storage padding that edit to the line break, grows the heading and moves the content.
        moved = shifted(NSRange(location: NSMaxRange(beta.headingRange), length: 0), " two")
        XCTAssertEqual(moved.headingLocation, beta.headingLocation)
//
//  StagedStylingTests.swift
//  MarkdownEngineTests
//
//  A large document opens with only its head styled; the rest is styled and laid
//  out in background turns, pulled forward under the viewport, and moved along by
//  edits. Whatever the order, the attributes must end up exactly as one full
//  restyle would leave them — the oracle every test here compares against.
//

import AppKit
import SwiftUI
import Testing
@testable import MarkdownEngine

@MainActor
private func makeEditor() -> (NativeTextViewCoordinator, NativeTextView, ClampedScrollView) {
    _ = NSApplication.shared   // selection path reads NSApp.currentEvent
    let coordinator = NativeTextViewCoordinator(
        text: .constant(""), fontName: "SF Pro Text", fontSize: 14,
        isWikiLinkActive: .constant(false), onLinkClick: nil, onInlineSelectionChange: nil
    )
    let stack = HeightBehaviorStack(viewport: NSSize(width: 600, height: 400))
    stack.textView.isEditable = true
    stack.textView.delegate = coordinator
    coordinator.textView = stack.textView
    return (coordinator, stack.textView, stack.scrollView)
}

/// Around 180 kB: the default head plus four background chunks.
private func largeDocument(sections: Int = 900) -> String {
    var text = ""
    for index in 0..<sections {
        text += "## Section \(index)\n\n"
        text += "Paragraph \(index) with **bold**, *emphasis*, [link](https://example.invalid/\(index)), and `code`.\n\n"
        text += "- [ ] task \(index)\n- item\n\n1. first\n2. second\n\n> quote \(index)\n\n"
        text += "```swift\nlet value\(index) = \(index)\n```\n\n"
        if index % 40 == 0 {
            text += "| a | b |\n| --- | --- |\n| \(index) | x |\n\n"
        }
    }
    return text
}

/// The background turns are main-queue blocks; a main-actor test is itself one, so
/// it has to suspend for them to run.
@MainActor
private func pump(_ coordinator: NativeTextViewCoordinator, timeout: TimeInterval = 60) async {
    let deadline = Date(timeIntervalSinceNow: timeout)
    while coordinator.stagedStylingActive, Date() < deadline {
        try? await Task.sleep(for: .milliseconds(2))
    }
}

private let sampleStride = 11

private func expectSameStyle(
    _ staged: [[NSAttributedString.Key: AnyHashable]],
    _ reference: [[NSAttributedString.Key: AnyHashable]],
    sourceLocation: SourceLocation = #_sourceLocation
) {
    guard staged.count == reference.count else {
        Issue.record("sample counts differ: \(staged.count) vs \(reference.count)", sourceLocation: sourceLocation)
        return
    }
    if let index = zip(staged, reference).enumerated().first(where: { $0.element.0 != $0.element.1 })?.offset {
        let keys = Set(staged[index].keys).union(reference[index].keys).filter { staged[index][$0] != reference[index][$0] }
        let detail = keys.map { "\($0.rawValue): staged=\(String(describing: staged[index][$0])) reference=\(String(describing: reference[index][$0]))" }
        Issue.record("attributes differ at character \(index * sampleStride) in \(detail.joined(separator: " | "))",
                     sourceLocation: sourceLocation)
    }
}

/// Font, colour and paragraph attributes at sampled positions; attachments and images
/// are rendered per pass and never compare equal.
private func styleSamples(_ storage: NSAttributedString, stride: Int = sampleStride) -> [[NSAttributedString.Key: AnyHashable]] {
    var samples: [[NSAttributedString.Key: AnyHashable]] = []
    var index = 0
    while index < storage.length {
        var sample: [NSAttributedString.Key: AnyHashable] = [:]
        for (key, value) in storage.attributes(at: index, effectiveRange: nil) {
            if value is NSTextAttachment || value is NSImage { continue }
            if let hashable = value as? AnyHashable { sample[key] = hashable }
        }
        samples.append(sample)
        index += stride
    }
    return samples
}

