import AppKit
import Foundation
import MarkdownEngine
import Observation

enum SidebarStyle: String, CaseIterable, Identifiable {
    case unified
    case glass

    var id: String { rawValue }
    var title: String { self == .unified ? "Eine Fläche" : "Glas" }
}

enum AppearancePreset: String, CaseIterable, Identifiable {
    case native = "Native"
    case iowan = "Iowan"
    case github = "GitHub"
    case night = "Night"

    static let systemSansName = NSFont.systemFont(ofSize: 17).fontName
    static let systemMonospaceName = NSFont.monospacedSystemFont(ofSize: 14, weight: .regular).fontName

    var id: String { rawValue }

    var bodyFontNames: [String] {
        switch self {
        case .native: [Self.systemSansName, "Helvetica Neue"]
        case .iowan: ["Iowan Old Style", "Georgia", Self.systemSansName]
        case .github: ["Open Sans", "Helvetica Neue", Self.systemSansName]
        case .night: ["Helvetica Neue", Self.systemSansName]
        }
    }

    var codeFontNames: [String] {
        switch self {
        case .native, .iowan, .github: [Self.systemMonospaceName, "Menlo", "Monaco"]
        case .night: ["Monaco", "Menlo", Self.systemMonospaceName]
        }
    }
}

struct ResolvedAppearance {
    let body: NSFont
    let code: NSFont
    let bodyRequestedFontIsUnavailable: Bool
    let codeRequestedFontIsUnavailable: Bool
}

struct AppearanceFontResolver {
    private let availableFontNames: Set<String>

    init(
        availableFontNames: [String] = NSFontManager.shared.availableFontFamilies
            + NSFontManager.shared.availableFonts
    ) {
        self.availableFontNames = Set(availableFontNames)
    }

    func resolve(
        preset: AppearancePreset,
        requestedBody: String,
        requestedCode: String,
        bodySize: CGFloat = 17,
        codeSize: CGFloat = 14
    ) -> ResolvedAppearance {
        let bodyRequested = font(named: requestedBody, size: bodySize)
        let codeRequested = font(named: requestedCode, size: codeSize)
        return ResolvedAppearance(
            body: bodyRequested ?? firstFont(in: preset.bodyFontNames, size: bodySize) ?? .systemFont(ofSize: bodySize),
            code: codeRequested ?? firstFont(in: preset.codeFontNames, size: codeSize)
                ?? .monospacedSystemFont(ofSize: codeSize, weight: .regular),
            bodyRequestedFontIsUnavailable: bodyRequested == nil,
            codeRequestedFontIsUnavailable: codeRequested == nil
        )
    }

    private func firstFont(in names: [String], size: CGFloat) -> NSFont? {
        names.lazy.compactMap { font(named: $0, size: size) }.first
    }

    private func font(named name: String, size: CGFloat) -> NSFont? {
        guard availableFontNames.contains(name) else { return nil }
        return NSFont(name: name, size: size)
    }
}

final class PTypeSyntaxHighlighter: SyntaxHighlighter, @unchecked Sendable {
    private let appearanceDidChange = Notification.Name("eu.bunk.ptype.appearance-did-change.\(UUID().uuidString)")
    private let lock = NSLock()
    private var font = NSFont.monospacedSystemFont(ofSize: 14, weight: .regular)

    func update(codeFont: NSFont) {
        lock.withLock { font = codeFont }
        NotificationCenter.default.post(name: appearanceDidChange, object: nil)
    }

    func codeFont(size: CGFloat) -> NSFont {
        lock.withLock { font }
    }

